ALTER TABLE "materials" ADD COLUMN "featured_regions" jsonb DEFAULT '[]'::jsonb NOT NULL;--> statement-breakpoint
-- Featured on Evidence per region, as on Duda (crawl 2026-11-05; src/lib/material.ts → FEATURED_ON_DUDA). The highlight flag
-- stays for News and home only. A material featured in a region is shown there; per region one record (the oldest id).
UPDATE "materials" SET "featured" = false WHERE "show_in_evidence" AND NOT "show_in_news";--> statement-breakpoint
UPDATE "materials" SET "featured_regions" = "featured_regions" || '["us"]'::jsonb, "regions" = CASE WHEN jsonb_array_length("regions") = 0 OR "regions" @> '["us"]'::jsonb THEN "regions" ELSE "regions" || '["us"]'::jsonb END WHERE "id" = (SELECT min("id") FROM "materials" WHERE "show_in_evidence" AND "title" ILIKE 'Radially adjustable Tigertriever demonstrates higher reperfusion%' AND (jsonb_array_length("regions") = 0 OR "regions" @> '["us"]'::jsonb OR NOT EXISTS (SELECT 1 FROM "materials" m2 WHERE m2."show_in_evidence" AND m2."title" ILIKE 'Radially adjustable Tigertriever demonstrates higher reperfusion%' AND (jsonb_array_length(m2."regions") = 0 OR m2."regions" @> '["us"]'::jsonb))));--> statement-breakpoint
